<?php
namespace App\Http\Controllers;
use App\Models\{PriceHistory,Product};use App\Services\PricingIntelligenceService;use Illuminate\Http\Request;
class PricingController extends Controller {
 public function index(Request $r){$products=Product::with('currentCosts')->orderBy('name')->get();$selected=$r->integer('product_id')?Product::with('currentCosts')->findOrFail($r->integer('product_id')):null;$history=$selected?PriceHistory::where('product_id',$selected->id)->latest('effective_from')->limit(20)->get():collect();return view('pricing.index',compact('products','selected','history'));}
 public function calculate(Request $r,PricingIntelligenceService $service){$d=$r->validate(['product_id'=>'required|exists:products,id','selling_price'=>'nullable|numeric|min:0|max:9999999999','other_unit_cost'=>'nullable|numeric|min:0|max:9999999999','marketplace_fee_percent'=>'required|numeric|between:0,100','ad_cost_percent'=>'required|numeric|between:0,100','target_margin_percent'=>'required|numeric|between:0,90','save'=>'nullable|boolean']);$product=Product::with('currentCosts')->findOrFail($d['product_id']);$result=$service->calculate($product,$d);if($r->boolean('save')){PriceHistory::create($result+['product_id'=>$product->id,'effective_from'=>now()->toDateString(),'created_by'=>auth()->id()]);$product->update(['target_selling_price'=>$result['target_price']]);}return redirect()->route('pricing.index',['product_id'=>$product->id])->with('pricing_result',$result)->with('success',$r->boolean('save')?'Price analysis saved to history.':'Price analysis calculated.');}
}
